#!/usr/bin/env node
/**
 * verify-schema-drift.mjs — prove the committed schema still matches the live project.
 *
 *   SUPABASE_ACCESS_TOKEN=<your-personal-access-token> \
 *     node scripts/verify-schema-drift.mjs [--ref REF]
 *
 * The dump in `isotope-complete.sql` is generated by introspecting the live
 * project, so it is only correct at the moment it is generated. Everything after
 * that is drift, and drift is silent: nothing fails, the schema just stops
 * reproducing the database it claims to describe.
 *
 * That is not hypothetical. `schema-dump.mjs` de-duplicated function grants with a
 * running `prevSig` while its query returned one row per (signature, grantee), so
 * it kept only the alphabetically-first grantee per function. 154 EXECUTE grants
 * were dropped — every `service_role` grant and 79 of 80 `authenticated` grants.
 * The dump still looked complete: every table, function, policy and trigger was
 * there. The only way to notice was to count grants per role against live.
 *
 * So this checks by NAME, per object class, and reports every difference in both
 * directions. Counts alone are not enough — a wrong count can be two errors
 * cancelling out.
 *
 * ONE STATEMENT PER REQUEST, deliberately. `POST /v1/projects/<ref>/database/query`
 * can return success for a multi-statement payload while applying only part of it,
 * which is how a verification step ends up verifying less than it claims.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const MGMT = 'https://api.supabase.com';
const DUMP = path.join(ROOT, 'isotope-complete.sql');

const argv = process.argv.slice(2);
const refArg = argv.find((a) => a.startsWith('--ref'))?.split('=')[1]
  || argv[argv.indexOf('--ref') + 1]
  || process.env.SUPABASE_REF
  || '';
const PAT = process.env.SUPABASE_ACCESS_TOKEN || '';

if (!PAT || !refArg) {
  console.error('usage: SUPABASE_ACCESS_TOKEN=<token> node scripts/verify-schema-drift.mjs --ref <project-ref>');
  process.exit(2);
}

async function q(sql) {
  // The management API intermittently drops the connection ("fetch failed") under
  // a burst of one-statement requests. That is a transport hiccup, not a schema
  // error, so retry rather than reporting a check that never ran.
  let res;
  for (let attempt = 0; attempt < 3; attempt++) {
    try {
      res = await fetch(`${MGMT}/v1/projects/${refArg}/database/query`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${PAT}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ query: sql }),
      });
      break;
    } catch (e) {
      if (attempt === 2) throw new Error(`transport: ${e.message}`);
      await new Promise((r) => setTimeout(r, 800 * (attempt + 1)));
    }
  }
  const text = await res.text();
  let body;
  try { body = text ? JSON.parse(text) : []; } catch { body = []; }
  if (!res.ok) throw new Error((body && (body.message || body.error)) || `HTTP ${res.status}`);
  return Array.isArray(body) ? body : [];
}

// Each inventory is a single statement. Names only — that is the contract:
// a dump that has drifted will differ in NAME, and comparing names catches
// "missing", "extra" and "renamed" in one pass.
const INVENTORIES = [
  ['tables', `select c.relname n from pg_class c join pg_namespace s on s.oid=c.relnamespace
    where s.nspname='public' and c.relkind='r' order by 1`],
  ['rls_enabled', `select c.relname n from pg_class c join pg_namespace s on s.oid=c.relnamespace
    where s.nspname='public' and c.relkind='r' and c.relrowsecurity order by 1`],
  // Return type included on purpose: identity args alone cannot see a drifted
  // signature, which is the 42P13 case ("cannot change return type").
  ['functions', `select p.proname||'('||pg_get_function_identity_arguments(p.oid)||')->'||pg_get_function_result(p.oid) n
    from pg_proc p join pg_namespace s on s.oid=p.pronamespace
    where s.nspname in ('public','private','rpc_private') and p.prolang <> 12
      and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')
    order by 1`],
  ['triggers', `select t.tgname||' @ '||c.relname n from pg_trigger t
    join pg_class c on c.oid=t.tgrelid join pg_namespace s on s.oid=c.relnamespace
    where s.nspname in ('public','auth') and not t.tgisinternal order by 1`],
  ['policies_public', `select policyname||' @ '||tablename n from pg_policies
    where schemaname='public' order by 1`],
  ['policies_storage', `select policyname||' @ '||tablename n from pg_policies
    where schemaname='storage' order by 1`],
  // Only indexes the dump emits as CREATE INDEX. Live also has the index behind
  // every PRIMARY KEY / UNIQUE constraint, which the dump creates via
  // ALTER TABLE ADD CONSTRAINT instead — counting those would report 58 phantom
  // "missing" indexes forever.
  ['indexes', `select c.relname n from pg_class c join pg_namespace s on s.oid=c.relnamespace
    where s.nspname='public' and c.relkind='i'
      and not exists (select 1 from pg_constraint k where k.conindid=c.oid and k.contype in ('p','u','x'))
    order by 1`],
  ['fk_constraints', `select con.conname||' @ '||c.relname n from pg_constraint con
    join pg_class c on c.oid=con.conrelid
    where con.contype='f' and con.connamespace='public'::regnamespace order by 1`],
  ['unique_constraints', `select con.conname||' @ '||c.relname n from pg_constraint con
    join pg_class c on c.oid=con.conrelid
    where con.contype='u' and con.connamespace='public'::regnamespace order by 1`],
  ['buckets', `select id n from storage.buckets order by 1`],
];

// Grants are compared PER ROLE. A total is not enough — the bug that motivated
// this file dropped 154 grants while the total looked plausible.
const GRANT_CHECKS = [
  ['table_grants', `select (select rolname from pg_roles where oid=g.grantee)||':'||c.relname||':'||g.privilege_type n
    from pg_class c join pg_namespace s on s.oid=c.relnamespace
    cross join lateral aclexplode(c.relacl) g
    where s.nspname='public' and c.relkind='r'
      and (select rolname from pg_roles where oid=g.grantee) in ('anon','authenticated','service_role')
      and g.privilege_type <> 'MAINTAIN' order by 1`],
  ['function_grants', `select (select rolname from pg_roles where oid=g.grantee)||':'||p.proname||':'||g.privilege_type n
    from pg_proc p join pg_namespace s on s.oid=p.pronamespace
    cross join lateral aclexplode(p.proacl) g
    where s.nspname in ('public','private','rpc_private')
      and (select rolname from pg_roles where oid=g.grantee) in ('anon','authenticated','service_role')
      and g.privilege_type <> 'MAINTAIN'
      and not exists (select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')
    order by 1`],
];

const dump = fs.readFileSync(DUMP, 'utf8');
const uniq = (a) => [...new Set(a)].sort();

// The dump is SQL text, so each class is matched with a targeted pattern rather
// than by executing it. Over-matching would create false "drifted" noise, so the
// patterns are deliberately anchored.
function fromDump(re) {
  const out = [];
  for (const m of dump.matchAll(re)) out.push(m[1]);
  return uniq(out);
}

const DUMP_PATTERNS = {
  tables: fromDump(/CREATE TABLE IF NOT EXISTS "public"\."([a-z_0-9]+)"/g),
  rls_enabled: fromDump(/ALTER TABLE "public"\."([a-z_0-9]+)" ENABLE ROW LEVEL SECURITY/g),
  triggers: uniq([...dump.matchAll(/CREATE TRIGGER ([a-z_0-9]+) (?:BEFORE|AFTER) [\s\S]*? ON ([a-z_]+)\.([a-z_0-9]+)/g)]
    .map((m) => `${m[1]} @ ${m[3]}`)),
  policies_public: uniq([...dump.matchAll(/CREATE POLICY "([^"]+)" ON "public"\."([a-z_0-9]+)"/g)]
    .map((m) => `${m[1]} @ ${m[2]}`)),
  policies_storage: uniq([...dump.matchAll(/CREATE POLICY "([^"]+)" ON storage\."objects"/g)]
    .map((m) => `${m[1]} @ objects`)),
  indexes: fromDump(/CREATE (?:UNIQUE )?INDEX IF NOT EXISTS ([a-z_0-9]+) ON public\./g),
  fk_constraints: uniq([...dump.matchAll(/ALTER TABLE ONLY "public"\."([a-z_0-9]+)" ADD CONSTRAINT "([a-z_0-9]+)" FOREIGN KEY/g)]
    .map((m) => `${m[2]} @ ${m[1]}`)),
  unique_constraints: uniq([...dump.matchAll(/ALTER TABLE ONLY "public"\."([a-z_0-9]+)" ADD CONSTRAINT "([a-z_0-9]+)" UNIQUE/g)]
    .map((m) => `${m[2]} @ ${m[1]}`)),
  buckets: fromDump(/INSERT INTO storage\.buckets[^;]*VALUES \('([a-z_0-9-]+)'/g),
};

function dumpGrants(kind) {
  const out = [];
  const re = kind === 'table_grants'
    ? /GRANT ([A-Z, ]+) ON (?:TABLE|SEQUENCE) "?[a-z_]+"?\."?([a-z_0-9]+)"? TO ([a-z_]+)/g
    : /GRANT ([A-Z, ]+) ON FUNCTION "?[a-z_]+"?\."?([a-z_0-9]+)"?\([^)]*\) TO ([a-z_]+)/g;
  for (const m of dump.matchAll(re)) {
    for (const priv of m[1].split(',').map((x) => x.trim()).filter(Boolean)) {
      out.push(`${m[3]}:${m[2]}:${priv}`);
    }
  }
  return uniq(out);
}

function diff(label, liveRows, dumpNames) {
  const live = uniq(liveRows.map((r) => r.n));
  const missing = live.filter((x) => !dumpNames.includes(x));
  const extra = dumpNames.filter((x) => !live.includes(x));
  const ok = missing.length === 0 && extra.length === 0;
  const mark = ok ? 'ok  ' : 'DRIFT';
  console.log(`  ${mark} ${label.padEnd(22)} live=${String(live.length).padStart(4)}  dump=${String(dumpNames.length).padStart(4)}`);
  if (missing.length) {
    console.log(`         missing from dump (${missing.length}): ${missing.slice(0, 8).join(', ')}${missing.length > 8 ? ' …' : ''}`);
  }
  if (extra.length) {
    console.log(`         not live (${extra.length}): ${extra.slice(0, 8).join(', ')}${extra.length > 8 ? ' …' : ''}`);
  }
  return ok;
}

console.log(`schema drift: ${refArg}  vs  ${path.relative(ROOT, DUMP)}\n`);

let allOk = true;
for (const [label, sql] of INVENTORIES) {
  let live;
  try {
    live = await q(sql);
  } catch (e) {
    console.log(`  ERR  ${label.padEnd(22)} ${e.message.slice(0, 110)}`);
    allOk = false;
    continue;
  }
  const names = live.map((r) => r.n);
  let dumpNames;
  if (label === 'functions') {
    // Rebuild the same shape from the dump text, including the return type.
    // The dump spells out parameter DEFAULTs; live's identity-arguments form omits
    // them. Compare on the identity form, which is what Postgres itself keys on.
    const splitTop = (a) => {
      const parts = []; let depth = 0, cur = '';
      for (const ch of a) {
        if (ch === '(' || ch === '[') depth++;
        if (ch === ')' || ch === ']') depth--;
        if (ch === ',' && depth === 0) { parts.push(cur); cur = ''; continue; }
        cur += ch;
      }
      if (cur.trim()) parts.push(cur);
      return parts;
    };
    const stripDefaults = (a) => splitTop(a)
      .map((x) => x.trim())
      .filter(Boolean)
      .map((x) => x.replace(/\s+DEFAULT\s+[\s\S]*$/i, '').trim())
      .map((x) => x.replace(/\s+/g, ' '))
      .join(', ');
    dumpNames = uniq([...dump.matchAll(
      /CREATE OR REPLACE FUNCTION "?[a-z_]+"?\."?([a-z_0-9]+)"?\(((?:[^()]|\([^()]*\))*)\)\s*\n?\s*RETURNS ([^\n]+)/g,
    )].map((m) => {
      const args = stripDefaults(m[2]);
      const ret = m[3].trim().replace(/\s+/g, ' ').trim();
      return `${m[1]}(${args})->${ret}`;
    }));
  } else {
    dumpNames = DUMP_PATTERNS[label] || [];
  }
  if (!diff(label, live, dumpNames)) allOk = false;
}

for (const [label, sql] of GRANT_CHECKS) {
  let live;
  try {
    live = await q(sql);
  } catch (e) {
    console.log(`  ERR  ${label.padEnd(22)} ${e.message.slice(0, 110)}`);
    allOk = false;
    continue;
  }
  if (!diff(label, live, dumpGrants(label))) allOk = false;
}

console.log('');
if (allOk) {
  console.log('no drift — the dump reproduces the live project');
  process.exit(0);
}
console.log('DRIFT: the dump no longer reproduces the live project.');
console.log('Regenerate:  node scripts/schema-dump.mjs   (then commit isotope-complete.sql)');
process.exit(1);
